mapper.select:
select s.signup_id, s.activity_id, s.name, s.student_no, s.college, s.major, s.signup_time, s.audit_status, s.audit_remark, s.auditor_id, s.auditor_name, s.audit_time, a.name as activity_name, a.duration_hours from oa_volunteer_signup s join oa_volunteer_activity a on a.activity_id = s.activity_id and a.del_flag = '0' where s.activity_id = #{activityId}
and s.audit_status = #{auditStatus}
and (s.name like concat('%', #{keyword}, '%') or s.student_no like concat(#{keyword}, '%'))
order by s.signup_time desc, s.signup_id desc

mapper.insert:
insert into oa_volunteer_signup (
    activity_id, name, student_no, college, major, signup_time, audit_status
) values (
    #{activityId}, #{name}, #{studentNo}, #{college}, #{major}, sysdate(), '0'
)

mapper.update:
update oa_volunteer_signup set audit_status = #{auditStatus}, audit_remark = #{auditRemark}, auditor_id = #{auditorId}, auditor_name = #{auditorName}, audit_time = sysdate() where signup_id in
#{item}
and exists (select 1 from oa_volunteer_activity a where a.activity_id = oa_volunteer_signup.activity_id and a.del_flag = '0')

mapper.select:
select s.signup_id, s.activity_id, s.name, s.student_no, s.college, s.major,
       s.signup_time, s.audit_status, s.audit_remark, s.auditor_id, s.auditor_name, s.audit_time,
       a.name as activity_name, a.duration_hours
from oa_volunteer_signup s
join oa_volunteer_activity a on a.activity_id = s.activity_id and a.del_flag = '0'
where s.student_no = #{studentNo}
  and s.name = #{name}

    and s.activity_id = #{activityId}

order by s.signup_time desc, s.signup_id desc
limit 1
